INSERT INTO `disaster_reports` (`id`, `tracking_code`, `barangay_id`, `purok_name`, `coordinates_lat`, `coordinates_lng`, `incident_location`, `disaster_type`, `severity`, `urgency`, `aid_support`, `affected_families`, `affected_individuals`, `displaced_families`, `casualties_count`, `injuries_count`, `missing_count`, `requested_assistance`, `situation_overview`, `resolution_notes`, `status`, `submitted_by`, `created_at`, `updated_at`, `completed_at`) VALUES (1,'REQ-2026-001',12,'Purok Riverside 1 & 2',8.246800,124.258800,'Purok Riverside 1 & 2, Hinaplanon','Flood','Critical','Immediate','resources',350,1540,220,0,4,0,'Requesting urgent dispatch of 350 Family Food Packs, 200 Hygiene Kits, 2 Inflatable Rescue Boats with operators, and 60 Life Vests due to rising Mandulog River overflow.','Mandulog river level reached 4.2 meters (Red Warning Stage). Water has entered low-lying residential clusters in Purok Riverside 1 and 2. 220 families already evacuated to Hinaplanon NHS Gym.',NULL,'Ongoing',2,'2026-10-03 18:46:32','2026-10-03 22:46:32',NULL),(2,'REQ-2026-002',38,'Purok 1 Baybay',8.214800,124.237200,'Purok 1 Baybay, Tomas Cabili','Storm Surge','High','High','resources',180,790,95,0,1,0,'Requesting 180 Family Food Packs, 100 Hygiene Kits, 50 Modular Tents, and First Aid replenishment for coastal evacuees.','High tide coupled with localized squall caused 1.8-meter sea swells battering coastal households along Purok 1 Baybay.',NULL,'Ongoing',3,'2026-10-02 22:46:32','2026-10-03 22:46:32',NULL),(3,'REQ-2026-003',12,'Purok San Miguel',8.245500,124.259800,'Purok San Miguel, Hinaplanon','Flash Flood','Moderate','Medium','resources',90,395,25,0,0,0,'Pre-emptive prepositioning of 90 Food Packs and 2 Portable Water Pumps in case creek drainage overflows.','Heavy continuous rain recorded over the hinterlands. Creek drainage in Purok San Miguel experiencing sluggish runoff.',NULL,'Ongoing',2,'2026-10-03 20:46:32','2026-10-03 22:46:32',NULL);
