INSERT INTO `notifications` VALUES (1,'all',12,NULL,'Mandulog River Red Warning Stage','PAGASA and City Hydromet sensors indicate Mandulog River water stage has exceeded 4.0 meters. Residents in Purok Riverside 1, 2 and low-lying zones must execute pre-emptive evacuation immediately to designated centers.','urgent','disaster_request',1,1,'2026-10-03 19:46:32'),(2,'icdrrmo',NULL,NULL,'Pending Decision Tree Recommendation #REC-2026-001','A Decision Tree resource recommendation of 350 Food Packs, 200 Hygiene Kits, and 2 Rescue Boats for Barangay Hinaplanon is awaiting administrative review.','warning','recommendation',1,2,'2026-10-03 19:46:32'),(3,'all',NULL,NULL,'Notice: 4th Quarter Nationwide Simultaneous Earthquake Drill','All barangay disaster coordinators, rescuer teams, and residents are invited to participate in the upcoming NSED scheduled on October 15, 2026 at 9:00 AM.','informational','preparedness',1,1,'2026-10-01 22:46:32'),(4,'barangay_head',38,NULL,'Resource Allocation Approved: Request #REQ-2026-002','ICDRRMO has approved and dispatched 180 Food Packs, 100 Hygiene Kits, and 50 Modular Tents for Purok 1 Baybay coastal surge response.','informational','disaster_request',2,1,'2026-10-03 04:46:32'),(5,'icdrrmo',1,NULL,'Active Incident: REQ-2026-004','Active disaster incident (Flood - Critical) reported by Brgy. Abuno (Purok 1 Baybay). Status is Ongoing.','urgent','disaster_request',4,NULL,'2026-10-05 17:45:57'),(6,'barangay_head',1,NULL,'Requisition Approved: TEST-REQ-20261005-519','Your Resource Requisition TEST-REQ-20261005-519 for 10 packs of Standard Family Food Pack (3-day ration) has been APPROVED by ICDRRMO. Remarks: Approved test','','resource_request',2,NULL,'2026-10-05 18:24:28'),(7,'barangay_head',1,NULL,'Requisition Rejected: TEST-REQ-REJ-394','Your Resource Requisition TEST-REQ-REJ-394 (Satellite Phones) was REJECTED by ICDRRMO. Reason: Reserved for City Headquarters command post.','warning','resource_request',3,NULL,'2026-10-05 18:24:28'),(8,'all',12,NULL,'Scheduled: asdqwe','New community preparedness activity scheduled: asdqwe at asdasd on 2026-10-07T12:00.','informational','preparedness',5,2,'2026-10-06 12:14:54'),(10,'all',12,NULL,'Scheduled: ffff','New community preparedness activity scheduled: ffff at fff on 2026-10-07T12:00.','informational','preparedness',6,2,'2026-10-06 12:35:05'),(11,'all',12,NULL,'Scheduled: zzz','New community preparedness activity scheduled: zzz at zzzz on 2026-10-07T12:00.','informational','preparedness',7,2,'2026-10-06 12:38:07'),(12,'all',12,NULL,'Scheduled: eee','New community preparedness activity scheduled: eee at eeee on 2026-10-07T13:00.','informational','preparedness',8,2,'2026-10-06 13:22:05'),(13,'all',12,NULL,'Scheduled: asasas','New community preparedness activity scheduled: asasas at asasas on 2026-10-07T13:00.','informational','preparedness',9,2,'2026-10-06 13:31:57'),(14,'all',12,NULL,'Scheduled: yyy','New community preparedness activity scheduled: yyy at yyy on 2026-10-07T14:00.','informational','preparedness',10,2,'2026-10-06 14:27:01'),(15,'all',12,NULL,'Scheduled: sample','New community preparedness activity scheduled: sample at sample1 on 2026-10-07T14:00.','informational','preparedness',11,2,'2026-10-06 14:35:00');
