INSERT INTO `recommendations` (`id`, `recommendation_code`, `disaster_request_id`, `priority`, `modality`, `confidence_score`, `decision_path`, `recommendation_reason`, `financial_aid_source`, `financial_aid_added_type`, `status`, `reviewed_by`, `reviewed_at`, `review_remarks`, `created_at`) VALUES (1,'REC-2026-001',1,'Critical','resources',92.40,'Root [Disaster: Flood] -> Branch [Severity: Critical (Water Depth > 1.5m)] -> Branch [Population: 350 Families] -> Branch [Urgency: Immediate] -> Stock Feasibility Check [Central Depot Available: Food Packs 1850 >= 350; Rescue Boats 7 >= 2; PFDs 310 >= 60; Hygiene Kits 680 >= 200] -> Outcome: Standard Tier-1 Critical Flood Package Activated.','Model evaluated disaster conditions: River overflow in Purok Riverside 1 & 2 (Mandulog watershed), critical severity with 350 affected families (220 displaced). Recommends 1:1 NDRRMC family food pack ration for immediate 3-day buffer, 2 water rescue boats based on swift current hazard, 60 Type-III PFDs for evacuee extraction, and 200 hygiene kits for camp sanitation. High stock sufficiency verified at Central Depot.','LGU Calamity Fund (QRF)','ai_recommended','Pending Review',NULL,NULL,NULL,'2026-10-03 19:46:32'),(2,'REC-2026-002',2,'High','resources',88.50,'Root [Disaster: Storm Surge] -> Branch [Severity: High (Coastal Inundation)] -> Branch [Population: 180 Families (95 Displaced)] -> Branch [Urgency: High] -> Stock Feasibility Check [Food Packs: 180; Hygiene Kits: 100; Modular Tents: 50] -> Outcome: Tier-2 Coastal Displacement Package.','Based on coastal surge impact displacing 95 families to Tomas Cabili Central School, the model recommends 180 food packs, 100 hygiene kits, and 50 modular privacy tents to safeguard evacuees and mitigate camp overcrowding disease risk.','LGU Calamity Fund (QRF)','ai_recommended','Approved',1,'2026-10-03 04:46:32','Approved by ICDRRMO Operations Officer. Dispatch authorized from Depot A & Depot C under convoy clearance.','2026-10-03 00:46:32');
