INSERT INTO `responder_field_updates` VALUES (1,4,1,12,'Purok Riverside 1','On Site','Water level along Purok Riverside 1 has crested at 1.4 meters in the lowest cluster. Team Alpha has deployed 1 rescue craft. 18 senior citizens and children successfully assisted to secondary high ground.',0,2,28,'1 Inflatable Rescue Boat, 12 Life Vests, 1 First Aid Kit','Creek current rapid. Requesting additional spotters on Mandulog bridge.','2026-10-03 21:46:32'),(2,5,2,38,'Purok 1 Baybay','Completed','Assisted evacuation of 95 families into Tomas Cabili Central School. Distributed initial 180 food packs and 50 modular tents. Medical triage station established at room 102.',0,1,0,'180 Food Packs, 50 Modular Tents, Trauma bandaging kit','Two minor lacerations treated. Evacuee registry submitted to MSWDO.','2026-10-03 08:46:32');
INSERT INTO `sms_logs` VALUES (1,'09701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new community event has been scheduled in your barangay:\nEvent: asdqwe\nVenue: asdasd\nStart: Oct 07, 2026 12:00 PM\nEnd: Oct 07, 2026 03:00 PM\nLead Facilitator: asdasdasd\nDetails: asdasd\nPlease be guided accordingly. Thank you!','sent',NULL,'event_created',5,'2026-10-06 12:22:23'),(2,'09701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new event has been scheduled in your barangay:\nEvent: ffff\nVenue: fff\nStart: Oct 07, 2026 12:00 PM\nEnd: Oct 07, 2026 03:00 PM\nLead Facilitator: fff\nDetails: ffff\nPlease be guided accordingly. Thank you!','sent',NULL,'event_created',6,'2026-10-06 12:35:05'),(3,'09701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new event has been scheduled in your barangay:\nEvent: zzz\nVenue: zzzz\nStart: Oct 07, 2026 12:00 PM\nEnd: Oct 07, 2026 03:00 PM\nLead Facilitator: zzz\nDetails: zzzz\nPlease be guided accordingly. Thank you!','sent',NULL,'event_created',7,'2026-10-06 12:38:07'),(4,'+639701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new community event has been scheduled in your barangay:\nEvent: asdqwe\nVenue: asdasd\nStart: Oct 07, 2026 12:00 PM\nEnd: Oct 07, 2026 03:00 PM\nLead Facilitator: asdasdasd\nDetails: asdasd\nPlease be guided accordingly. Thank you!','simulated (No API Key)','Notice: SMS Gateway API Key is not yet configured in backend/config/config.php (SMS_API_KEY). Message was logged into database successfully.','event_created',5,'2026-10-06 12:43:38'),(5,'+639701965951','angel nadayag','BARANGAY DISASTER ADVISORY\nHi angel nadayag!\nA new event has been scheduled in your barangay:\nEvent: eee\nVenue: eeee\nStart: Oct 07, 2026 01:00 PM\nEnd: Oct 07, 2026 04:00 PM\nLead Facilitator: eee\nDetails: eeee\nPlease be guided accordingly. Thank you!','failed','Your account has not yet been approved for sending messages. Please eith